mapper.select:
SELECT COUNT(*) FROM tb_car
WHERE del_yn = 'N' AND car_no = #{carNo}
AND car_id <> #{excludeId}

sql.where:
c.del_yn = 'N' AND c.company_code = #{companyCode} AND c.car_type = #{carType}
AND c.car_no LIKE '%' + #{keyword} + '%' AND c.car_name LIKE '%' + #{keyword} + '%'
AND (c.car_no LIKE '%' + #{keyword} + '%' OR c.car_name LIKE '%' + #{keyword} + '%')
